  sewNote:"金具の縫い付けが唯一の難所です。ミシンでは届かないので手縫いになりますが、ここを手抜きすると使っているうちに金具が外れます。糸を2本どりにして、穴1つにつき4〜5往復。玉結びは裏布と表布のあいだに隠せると美しく仕上がります。",
